#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, K;
    long long T;

    if (scanf("%d %d %lld", &N, &K, &T) != 3) {
        return 0;
    }

    int P[300];
    for (int i = 0; i < N; i++) {
        scanf("%d", &P[i]);
    }

    int initial[300];
    int count = 0;
    for (int i = 1; i <= N; i++) {
        int G;
        scanf("%d", &G);
        if (G) {
            initial[count++] = i;
        }
    }

    int width = 9 * K + 1;
    int *dp = malloc((size_t)(K + 1) * width * sizeof(int));
    if (dp == NULL) {
        return 0;
    }

    const int INF = 1000000000;
    for (int i = 0; i <= K; i++) {
        for (int s = 0; s < width; s++) {
            dp[i * width + s] = INF;
        }
    }
    dp[0] = 0;

    for (int j = 1; j <= N; j++) {
        int maxSelected = j < K ? j : K;
        for (int i = maxSelected; i >= 1; i--) {
            int distance = initial[i - 1] - j;
            if (distance < 0) distance = -distance;

            for (int s = 0; s <= 9 * (i - 1); s++) {
                int cost = dp[(i - 1) * width + s];
                if (cost == INF) continue;

                int newCost = cost + distance;
                int *destination = &dp[i * width + s + P[j - 1]];
                if (newCost < *destination) {
                    *destination = newCost;
                }
            }
        }
    }

    int answer = 0;
    for (int s = 0; s < width; s++) {
        if ((long long)dp[K * width + s] <= T) {
            answer = s;
        }
    }

    printf("%d\n", answer);
    free(dp);
    return 0;
}
